interface Camera {
    void takePhoto();
}

interface MusicPlayer {
    void playMusic(String track);
}

// SmartPhone implements BOTH interfaces
class SmartPhone implements Camera, MusicPlayer {
    private String model;

    public SmartPhone(String model) {
        this.model = model;
    }

    // Implementing Camera contract
    @Override
    public void takePhoto() {
        System.out.println(model + " takes a high-res 48MP photo: Click!");
    }

    // Implementing MusicPlayer contract
    @Override
    public void playMusic(String track) {
        System.out.println(model + " streams audio: " + track);
    }
}

public class InterfaceDemo {
    public static void main(String[] args) {
        SmartPhone phone = new SmartPhone("Galaxy S24");

        // Fulfilling Camera capability
        phone.takePhoto();

        // Fulfilling MusicPlayer capability
        phone.playMusic("Bohemian Rhapsody");
    }
}

