class Vehicle {
    protected String brand;

    public Vehicle(String brand) {
        this.brand = brand;
    }

    public void drive() {
        System.out.println(brand + " is driving down the highway.");
    }
}

interface Chargeable {
    void plugInCharger();
}

interface Autonomous {
    void enableAutopilot();
}

// Extends single superclass Vehicle AND implements two interfaces
class ElectricCar extends Vehicle implements Chargeable, Autonomous {
    public ElectricCar(String brand) {
        super(brand);
    }

    @Override
    public void plugInCharger() {
        System.out.println(brand + " plugged into 240V fast charger.");
    }

    @Override
    public void enableAutopilot() {
        System.out.println(brand + " autopilot engaged! Cameras active.");
    }
}

public class ElectricCarDemo {
    public static void main(String[] args) {
        ElectricCar tesla = new ElectricCar("Tesla Model S");
        tesla.drive();           // Inherited from Vehicle superclass
        tesla.plugInCharger();   // From Chargeable interface
        tesla.enableAutopilot(); // From Autonomous interface
    }
}

