interface Playable {
    void play();
}

interface Recordable {
    void record();
}

class TapeDeck implements Playable, Recordable {
    @Override
    public void play() {
        System.out.println("TapeDeck is playing cassette audio.");
    }

    @Override
    public void record() {
        System.out.println("TapeDeck is recording incoming audio.");
    }
}

public class Main {
    public static void main(String[] args) {
        TapeDeck deck = new TapeDeck();
        deck.play();
        deck.record();
    }
}

interface HeartRateMonitor {
    void measureBpm();
}

interface Pedometer {
    void countSteps(int steps);
}

class SmartWatch implements HeartRateMonitor, Pedometer {
    @Override
    public void measureBpm() {
        System.out.println("Current heart rate: 72 BPM");
    }

    @Override
    public void countSteps(int steps) {
        System.out.println("Steps recorded today: " + steps);
    }
}

public class Main {
    public static void main(String[] args) {
        SmartWatch watch = new SmartWatch();
        watch.measureBpm();
        watch.countSteps(8450);
    }
}

class Aircraft {
    protected String serialNumber;

    public Aircraft(String sn) {
        this.serialNumber = sn;
    }

    public void takeOff() {
        System.out.println(serialNumber + " is airborne.");
    }
}

interface AerialCamera {
    void snapAerialPhoto();
}

interface BatteryPowered {
    void checkBatteryLevel();
}

class Drone extends Aircraft implements AerialCamera, BatteryPowered {
    public Drone(String sn) {
        super(sn);
    }

    @Override
    public void snapAerialPhoto() {
        System.out.println(serialNumber + " snapped 4K aerial photo.");
    }

    @Override
    public void checkBatteryLevel() {
        System.out.println(serialNumber + " battery at 90%.");
    }
}

public class Main {
    public static void main(String[] args) {
        Drone drone = new Drone("DRONE-X1");
        drone.takeOff();
        drone.checkBatteryLevel();
        drone.snapAerialPhoto();
    }
}

