interface Validator {
    boolean isValid(String data);
}

interface Formatter {
    String format(String data);
}

class EmailProcessor implements Validator, Formatter {
    @Override
    public boolean isValid(String data) {
        return data != null && data.contains("@");
    }

    @Override
    public String format(String data) {
        return data.trim().toLowerCase();
    }
}

public class Main {
    public static void main(String[] args) {
        EmailProcessor processor = new EmailProcessor();
        String input = "  User@Domain.Com  ";

        Validator v = processor;
        System.out.println("Valid: " + v.isValid(input));

        Formatter f = processor;
        System.out.println("Formatted: '" + f.format(input) + "'");
    }
}
